import{_ as e,o as i,c as s,ag as a}from"./chunks/framework.DNmTgtHf.js";const p=JSON.parse('{"title":"Part 20 — Signing & Verification","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_20_Signing.md","filePath":"todo/study_plan/parts/Part_20_Signing.md"}'),n={name:"todo/study_plan/parts/Part_20_Signing.md"};function r(o,t,d,l,c,h){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="part-20-—-signing-verification" tabindex="-1">Part 20 — Signing &amp; Verification <a class="header-anchor" href="#part-20-—-signing-verification" aria-label="Permalink to &quot;Part 20 — Signing &amp; Verification&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 9 (shared). <strong>Budget: ~3-4 hrs.</strong></p></blockquote><h2 id="_20-signing-verification-—-topic-inventory" tabindex="-1">20 Signing &amp; Verification — topic inventory <a class="header-anchor" href="#_20-signing-verification-—-topic-inventory" aria-label="Permalink to &quot;20 Signing &amp; Verification — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Digital signature vs MAC — different threat models</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 15)</td></tr><tr><td>2</td><td>Sign-then-encrypt vs encrypt-then-sign — choose carefully</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>HMAC for symmetric scenarios (webhook signing)</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>1 hr 45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: HMAC-SHA256 over a JSON payload + base64-encode + constant-time verify (15 min)</td></tr><tr><td>4</td><td>RSA-PSS, ECDSA, EdDSA — modern signature algorithms</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>Webhook signing — Stripe-style HMAC, replay protection with timestamps</td><td>🔴 💼 🔐 🎯</td><td>D</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: build a webhook receiver that verifies HMAC over <code>timestamp + body</code> with 5-min replay window (30 min)</td></tr><tr><td>6</td><td>Detached signatures — for documents, JARs</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>JWS detached payloads</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Code signing</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Document signing — PDF signatures, eIDAS (Europe), relevant to KYC</td><td>🟠 💼 🔐</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~9.25 hrs</td><td>~0.85 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~14.75 hrs</td><td>~1.35 wk</td><td></td></tr><tr><td>Full Part (all items)</td><td>~14.75 hrs</td><td>~1.35 wk</td><td></td></tr></tbody></table><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>HMAC vs digital signature (side-by-side):</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph HMAC[&quot;HMAC (symmetric)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        direction TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        H1[&quot;Key model:&lt;br/&gt;shared symmetric secret&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        H2[&quot;Non-repudiation:&lt;br/&gt;NO — either side could sign&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        H3[&quot;Performance:&lt;br/&gt;fast (single hash pass)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        H4[&quot;Use cases:&lt;br/&gt;webhook signing,&lt;br/&gt;internal integrity,&lt;br/&gt;JWT HS256&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph SIG[&quot;Digital signature (asymmetric)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        direction TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S1[&quot;Key model:&lt;br/&gt;sender private,&lt;br/&gt;verifier public&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S2[&quot;Non-repudiation:&lt;br/&gt;YES — only signer&lt;br/&gt;holds private key&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S3[&quot;Performance:&lt;br/&gt;slower (RSA/ECDSA op)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        S4[&quot;Use cases:&lt;br/&gt;cross-org trust,&lt;br/&gt;KYC document signing,&lt;br/&gt;code signing, JWT RS256&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span></code></pre></div><blockquote><p>Pick HMAC when both sides are trusted; pick digital signature when the verifier should never be able to forge.</p></blockquote><p><strong>Webhook signing + replay defense:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    autonumber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as Sender</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant R as Receiver</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Cache as Redis (nonce store, TTL)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;S: sig = HMAC-SHA256(secret, ts + nonce + body)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;R: POST /webhook&lt;br/&gt;headers: X-Signature=sig, X-Timestamp=ts, X-Nonce=n&lt;br/&gt;body=...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R-&gt;&gt;R: (a) |now - ts| &lt; 5 min? else reject</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R-&gt;&gt;Cache: (b) SET nonce NX EX 600 (already-seen?)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Cache--&gt;&gt;R: ok / already exists</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    alt nonce already exists</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        R--&gt;&gt;S: 409 replay rejected</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    else fresh nonce</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        R-&gt;&gt;R: (c) expected = HMAC-SHA256(secret, ts + nonce + body)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        R-&gt;&gt;R: MessageDigest.isEqual(sig, expected)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        R--&gt;&gt;S: 200 OK (or 401 on mismatch)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span></code></pre></div><blockquote><p>Three checks: timestamp window stops ancient captures; nonce store stops in-window replays; constant-time HMAC compare stops timing leaks.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> HMAC vs digital signature — different threat models, when each fits? <ul><li><strong>Why asked:</strong> Senior-canonical. HMAC: shared secret, symmetric, both sides can sign + verify. Use when issuer and verifier are the same party (or tightly coupled). Digital signature: asymmetric, signer has private key, anyone with public key verifies. Use when verifier shouldn&#39;t be able to forge (cross-org webhooks, code signing, document signing).</li></ul></li><li><strong>Q:</strong> Design a webhook signing scheme for KYC partner notifications. <ul><li><strong>Why asked:</strong> Your KYC platform pattern. HMAC-SHA256 over <code>timestamp + &#39;:&#39; + body</code>. Send as <code>X-Signature: t=&lt;timestamp&gt;,v1=&lt;hex_hmac&gt;</code> header (Stripe style). Receiver: (1) parse timestamp + signature, (2) check |now - timestamp| &lt; 5 min (replay window), (3) recompute HMAC over <code>timestamp + &#39;:&#39; + raw_body</code>, (4) constant-time compare. Rotate secret periodically.</li></ul></li><li><strong>Q:</strong> Sign-then-encrypt vs encrypt-then-sign — which is right? <ul><li><strong>Why asked:</strong> Subtle senior crypto. Encrypt-then-sign is generally safer: the verifier can validate the signature WITHOUT decrypting (failure-fast, no oracle attacks). Sign-then-encrypt: verifier must decrypt first → attacker can manipulate ciphertext, forcing decryption attempts. For most use cases, prefer encrypt-then-sign (or AEAD primitive that does both).</li></ul></li><li><strong>Q:</strong> RSA-PSS vs RSA-PKCS#1 v1.5 — why prefer PSS? <ul><li><strong>Why asked:</strong> Modern crypto. PKCS#1 v1.5 padding has known weaknesses (Bleichenbacher attack on RSA encryption, various signature forgery side channels). RSA-PSS uses random salting + provable security reduction. Modern code: prefer PSS for RSA signatures, or better, switch to ECDSA / EdDSA.</li></ul></li><li><strong>Q:</strong> EdDSA (Ed25519) vs ECDSA — modern best practice? <ul><li><strong>Why asked:</strong> Crypto trend. Ed25519: deterministic (no nonce reuse), faster, smaller signatures, simpler implementation, no malleability. Recommended by current crypto guidance (e.g., RFC 8032). ECDSA: more deployed historically, requires careful nonce handling (Sony PS3 was hacked due to nonce reuse). New systems: use Ed25519.</li></ul></li><li><strong>Q:</strong> What&#39;s a detached signature, when used? <ul><li><strong>Why asked:</strong> Practical pattern. Signature stored separately from the signed data (e.g., <code>data.zip</code> + <code>data.zip.sig</code>). Use cases: signing existing artifacts without modifying them (released JARs, deployment bundles), audit logs (signature is appended without changing the data). Maven uses detached <code>.asc</code> signatures.</li></ul></li><li><strong>Q:</strong> Document signing for KYC — eIDAS requirements? <ul><li><strong>Why asked:</strong> Domain regulatory. eIDAS (EU regulation): three levels — Simple (clicked agreement), Advanced (verified identity + linked to signer), Qualified (Advanced + qualified certificate from Trust Service Provider, equivalent to handwritten signature). Different KYC use-cases require different levels.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your webhook signature verification fails because of JSON serialization order. <ul><li><strong>Gotcha:</strong> Canonical serialization. Two semantically-equivalent JSONs (<code>{&quot;a&quot;:1,&quot;b&quot;:2}</code> vs <code>{&quot;b&quot;:2,&quot;a&quot;:1}</code>) hash differently. Solution: (1) sign the raw body bytes (not the re-serialized JSON), (2) document the exact serialization on both ends, (3) use a canonical JSON form (RFC 8785 JSON Canonicalization Scheme).</li></ul></li><li><strong>Q:</strong> You verified an HMAC successfully but a customer disputes their signed transaction. What&#39;s missing? <ul><li><strong>Gotcha:</strong> HMAC = &quot;either party could have signed&quot; (symmetric secret). Doesn&#39;t provide non-repudiation. For non-repudiation, use digital signature (asymmetric). Customer can&#39;t claim &quot;your team signed on my behalf&quot; because only they have the private key.</li></ul></li><li><strong>Q:</strong> ECDSA with deterministic nonces (RFC 6979) vs random nonces — same security? <ul><li><strong>Gotcha:</strong> RFC 6979 (deterministic) is safer in practice — eliminates nonce reuse class of bugs (Sony PS3). Same theoretical security. Most modern libraries default to RFC 6979 (Bouncy Castle, libsodium). EdDSA is deterministic by design.</li></ul></li><li><strong>Q:</strong> Your replay-protection window is 5 min. An attacker captures a webhook and replays it 4 minutes later. What happens? <ul><li><strong>Gotcha:</strong> It succeeds. Replay window protects against ancient captures, not recent ones. Defense in depth: (1) add a nonce / message-ID, reject duplicates (requires server-side state), (2) require monotonic timestamp per source.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Webhook signing end-to-end for KYC partners</strong> (~3 hrs combined rows 3+5) — Stripe-style HMAC over <code>timestamp + body</code>, replay protection, key rotation. Implement sender + receiver, test both happy and attack paths.</li><li><strong>HMAC vs digital signature decision</strong> (~2 hrs row 1) — practical decision tree. When non-repudiation matters → asymmetric. When only integrity within an org → HMAC.</li><li><strong>Document signing for KYC compliance</strong> (~2.5 hrs row 9) — eIDAS levels, PDF signatures (PAdES), workflow integration with Privy.id or similar. Maps to your KYC platform&#39;s document handling.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up signing exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Stripe-style webhook signing implementation</strong> (~60 min) — sender computes <code>HMAC-SHA256(timestamp + &quot;:&quot; + body)</code> with shared secret. Header: <code>X-Signature: t=&lt;ts&gt;,v1=&lt;hex&gt;</code>. Receiver: parse, verify timestamp window (5 min), verify HMAC constant-time. Test: tampered body, expired timestamp, wrong secret.</li><li><strong>ECDSA Ed25519 sign + verify</strong> (~45 min) — generate keypair, sign a message, verify with public key. Then flip a bit of the message, observe verification fails. Compare with RSA-PSS for the same operation (timing + signature size).</li><li><strong>JWS detached signature</strong> (~45 min) — create a JWS with detached payload (signature only). Use case: signing existing files without re-encoding. Verify the signature against the original file.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Webhook signing key rotation</strong> (~75 min) — design: accept signatures from BOTH old + new keys during overlap window. After cutover, reject old. Implement with a key-set provider that returns active + previous keys. Test rotation without downtime.</li><li><strong>Reproduce ECDSA nonce-reuse attack</strong> (~90 min) — educational only. Sign two different messages with the SAME nonce (manually, breaking the deterministic-nonce best practice). Show how the private key can be recovered from the two signatures. Then switch to RFC 6979 deterministic nonces; observe the attack no longer applies.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5.25 hrs</strong></td><td><strong>~0.48 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~45 min for Part 20 across 2 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. HMAC vs digital signature — one-line distinction.</strong> A. HMAC: shared secret, symmetric, no non-repudiation. Digital signature: asymmetric, signer has private key, provides non-repudiation (signer can&#39;t deny later).</p><p><strong>Q. Webhook signing — what&#39;s in the signed payload?</strong> A. <code>timestamp + &#39;:&#39; + raw_body</code>. Plus a replay window (typically 5 min) to reject ancient captures. Plus shared-secret rotation.</p><p><strong>Q. Encrypt-then-sign vs sign-then-encrypt — preferred order?</strong> A. Encrypt-then-sign. Verifier can validate signature WITHOUT decrypting → fail-fast, no decryption oracle exposure. AEAD primitives like AES-GCM bundle both.</p><p><strong>Q. RSA-PSS vs PKCS#1 v1.5 — why prefer PSS?</strong> A. PSS uses random salt + provable security. PKCS#1 v1.5 has known weakness classes. New code: PSS or, better, switch to ECDSA / EdDSA.</p><p><strong>Q. EdDSA (Ed25519) advantages over ECDSA?</strong> A. Deterministic nonces (no nonce-reuse class of bugs), faster verify, smaller signatures (64 bytes), simpler implementation. Modern recommendation for new systems.</p><p><strong>Q. eIDAS signature levels?</strong> A. Simple (clicked), Advanced (verified identity, linked to signer), Qualified (Advanced + qualified cert from Trust Service Provider, legally equivalent to handwritten signature).</p>`,35)])])}const u=e(n,[["render",r]]);export{p as __pageData,u as default};
